INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das KISS-Prinzip nur für Anfänger?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Profis profitieren von Einfachheit"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem KISS-Prinzip?', 3, '[{"text": "Einfache Lösungen", "correct": true, "because": "Reduziert Komplexität"}, {"text": "Maximale Features", "correct": false, "because": "Nicht primär"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein direkter Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das KISS-Prinzip?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Einfacher Code verständlich"}, {"text": "Wartbarkeit", "correct": true, "because": "Leichter zu ändern"}, {"text": "Höhere Performance", "correct": false, "because": "Nicht garantiert"}, {"text": "Mehr Funktionen", "correct": false, "because": "Widerspricht KISS"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) KISS vermeidet Komplexität. b) Es verbietet Abstraktionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abstraktionen erlaubt, wenn einfach"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim KISS-Prinzip?', 4, '[{"text": "Klarheit", "correct": false, "because": "Kern des Prinzips"}, {"text": "Einfachheit", "correct": false, "because": "Hauptziel"}, {"text": "Unnötige Features", "correct": true, "because": "Sollen vermieden werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob KISS komplexe Lösungen erlaubt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Einfachheit"}, {"text": "Ja", "correct": false, "because": "Nur wenn nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem KISS-Prinzip?', 3, '[{"text": "Einfache Funktion statt Framework", "correct": true, "because": "Minimaler Ansatz"}, {"text": "Komplexe Klassenstruktur", "correct": false, "because": "Unnötig kompliziert"}, {"text": "Viele Abhängigkeiten", "correct": false, "because": "Erhöht Komplexität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördert das KISS-Prinzip?', 5, '[{"text": "Verständlichkeit", "correct": true, "because": "Klarer Code"}, {"text": "Schnelle Entwicklung", "correct": true, "because": "Weniger Aufwand"}, {"text": "Maximale Abstraktion", "correct": false, "because": "Nur wenn nötig"}, {"text": "Hoher Speicherbedarf", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) KISS erleichtert Wartung. b) Es verbietet Design-Patterns. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Patterns erlaubt, wenn einfach"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das KISS-Prinzip?', 4, '[{"text": "Klarheit", "correct": false, "because": "Zentrales Element"}, {"text": "Funktionalität", "correct": false, "because": "Muss erhalten bleiben"}, {"text": "Komplexe Frameworks", "correct": true, "because": "Oft überflüssig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist KISS ohne Planung möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Einfachheit kann intuitiv sein"}, {"text": "Nein", "correct": false, "because": "Planung hilft, nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst das KISS-Prinzip?', 4, '[{"text": "Überkomplexität", "correct": true, "because": "Vereinfacht Lösungen"}, {"text": "Schwere Lesbarkeit", "correct": true, "because": "Klarer Code"}, {"text": "Langsame Tests", "correct": false, "because": "Kein Testfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass KISS nur für kleine Projekte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch große profitieren"}, {"text": "Ja", "correct": false, "because": "Universell nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim KISS-Prinzip?', 3, '[{"text": "Einfachheit", "correct": true, "because": "Kern des Prinzips"}, {"text": "Viele Features", "correct": false, "because": "Widerspricht KISS"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) KISS fördert Verständlichkeit. b) Es garantiert immer weniger Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Code-Länge nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das KISS-Prinzip?', 5, '[{"text": "Eingeschränkte Komplexität", "correct": true, "because": "Kann Features begrenzen"}, {"text": "Übersimplifizierung", "correct": true, "because": "Kann Probleme übersehen"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein Performance-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim KISS-Prinzip unwichtig?', 3, '[{"text": "Klarheit", "correct": false, "because": "Zentrales Ziel"}, {"text": "Einfachheit", "correct": false, "because": "Kernprinzip"}, {"text": "Unnötige Abstraktionen", "correct": true, "because": "Sollen vermieden werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Macht KISS Code immer kürzer?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Einfachheit, nicht Länge"}, {"text": "Ja", "correct": false, "because": "Kürze nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob KISS Tests erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Einfacher Code prüfbar"}, {"text": "Nein", "correct": false, "because": "Testbarkeit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt das KISS-Prinzip?', 4, '[{"text": "DRY", "correct": true, "because": "Vermeidet Wiederholung"}, {"text": "LSP", "correct": false, "because": "Vererbungs-Fokus"}, {"text": "OCP", "correct": false, "because": "Erweiterungs-Fokus"}]');
